function accountValue(a){return a.cash+a.holdings.reduce((n,h)=>n+h.value,0)}
function totals(){let bonds=Object.values(state.positions).reduce((a,b)=>a+b,0),cash=state.cash,stocks=0;for(const [id,a] of Object.entries(ACCOUNTS)){if(!state.connected[id])continue;cash+=a.cash;for(const h of a.holdings){if(h.type==='Bonds')bonds+=h.value;else stocks+=h.value}}return {bonds,cash,stocks,total:bonds+cash+stocks}}
function syncURL(){const p=new URLSearchParams(location.search);p.set('view',state.view);if(state.variant!=='A'||p.has('variant'))p.set('variant',state.variant);history.replaceState({},'',`${location.pathname}?${p}`)}
