 if(state.overviewTab==='holdings')return `<div class="overview-holdings">${portfolioDetailsMarkup()}</div>`;
 if(state.overviewTab==='payments')return `<div id="payment-schedule-content">${PortfolioIncome.render(earningsSnapshot(),state.incomeMonth,ACCOUNTS)}</div>`;
