function activity(){const own=state.orders.slice().reverse().map(o=>`<div class="history-line"><div>${o.side==='buy'?'Bought':'Sold'} ${o.name}<small>InCreditble · Simulated fill · ${o.time}</small></div><strong>${o.side==='buy'?'−':'+'}${money(o.cents)}</strong></div>`).join('');const ext=Object.entries(ACCOUNTS).filter(([id])=>state.connected[id]).flatMap(([,a])=>a.activity.map(x=>`<div class="history-line"><div>${x.name}<small>${a.name} · ${x.action} · Oct 8, 2026</small></div><span>${money(x.amount)}</span></div>`)).join('');return own+ext||'<p class="muted">Your simulated trades will appear here.</p>'}
const holdingLabel=n=>Number(n)===0?'Less than 1 year':Number(n)===31?'30+ years':`Up to ${n} ${Number(n)===1?'year':'years'}`;
const bondTerm=b=>b.years<1?`${Math.round(b.years*12)} months`:`${b.years} ${b.years===1?'year':'years'}`;
const maturity=b=>new Date(Date.UTC(2026,9+Math.round(b.years*12),9)).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
const withinHoldingPeriod=(b,n)=>n===31|| (n===0?b.years<1:b.years<=n);
function recommendations(f=state.filters){return BONDS.filter(b=>b.risk<=maxRisk()&&b.yield>=f.yield&&(f.sector==='Any sector'||b.sector===f.sector)&&withinHoldingPeriod(b,Number(f.term))).sort((a,b)=>a.risk-b.risk||Math.abs(a.yield-f.yield)-Math.abs(b.yield-f.yield))}
function topMatches(eligible=recommendations()){return BondMatching.highlights(BondMatching.shortlist(eligible,{filters:state.filters,positions:state.positions,bonds:BONDS}),state.filters)}
function options(list,value){return list.map(([v,l])=>`<option value="${v}" ${String(value)===String(v)?'selected':''}>${l}</option>`).join('')}
function defaultRange(filters){const matches=recommendations(filters);if(!matches.length)return 'No matches';const rates=matches.map(b=>b.defaultRate),low=Math.min(...rates),high=Math.max(...rates);return low===high?pct(low):`${low.toFixed(2)}–${high.toFixed(2)}%`}
function defaultHelp(filters){return recommendations(filters).length?'Default rate: illustrative annual rate across all eligible demo bonds, before ranking the top three. Not a forecast.':'No demo bonds match your yield, industry, timeframe and risk preference, so no default rate is shown. Try a lower yield or broader filters.'}
// Hypothetical CD curve for UI comparison only: not bank quotes or market averages.
const CD_BENCHMARKS=[{years:0.5,apy:4.1},{years:1,apy:4.0},{years:2,apy:3.8},{years:3,apy:3.6},{years:4,apy:3.5},{years:5,apy:3.4}];
function cdBenchmark(term,target){
 const years=Number(term)===0?0.5:Number(term),cd=CD_BENCHMARKS.find(c=>c.years===years)||CD_BENCHMARKS[CD_BENCHMARKS.length-1],matched=years===cd.years;
 const tenor=cd.years<1?'6-month':`${cd.years}-year`,difference=Math.round((Number(target)-cd.apy)*100)/100;
 const comparison=!matched?'Shorter-term reference only. This demo has no CD quote for your selected horizon.':!Number(target)?'Set a yield target to compare.':difference===0?'Your target equals this sample APY.':`Your target is ${Math.abs(difference).toFixed(2)} percentage points ${difference>0?'higher':'lower'}.`;
 return `<div class="cd-heading"><span>Bank CD benchmark</span><span class="cd-sample">Example</span></div><div class="cd-rate"><strong>${pct(cd.apy)} <span>APY</span></strong><span>${tenor} fixed deposit</span></div><p class="cd-comparison">${comparison}</p><small>Illustrative rate · Not a live bank offer.</small>`;
}
function updateYieldPreview(){const form=$('#preferences');if(!form)return;const data=new FormData(form),value=Number(data.get('yield')),slider=$('#target-yield');$('#yield-value').textContent=value?pct(value):'Any yield';const filters={yield:value,sector:data.get('sector'),term:Number(data.get('term'))};$('#default-value').textContent=defaultRange(filters);$('#default-help').textContent=defaultHelp(filters);$('#cd-benchmark').innerHTML=cdBenchmark(filters.term,value);slider.style.setProperty('--progress',`${value/8*100}%`);slider.setAttribute('aria-valuetext',value?`${pct(value)} minimum annual yield`:'No minimum yield')}
function saveFinderDraft(){const form=$('#preferences');if(!form||!form.checkValidity())return;const d=new FormData(form);state.filters={amount:Number(d.get('amount')),yield:Number(d.get('yield')),sector:d.get('sector'),term:Number(d.get('term'))};saveDemo()}
function updateHoldingPreview(adjustYield=false){
 const form=$('#preferences');if(!form)return;const data=new FormData(form),term=Number(data.get('term')),slider=$('#holding-period');
 $('#holding-value').textContent=holdingLabel(term);slider.style.setProperty('--progress',`${term/31*100}%`);slider.setAttribute('aria-valuetext',holdingLabel(term));
 if(adjustYield){
  if(!state.yieldAuto)$('#holding-help').textContent=`Your ${Number(data.get('yield'))?pct(Number(data.get('yield'))):'no-minimum'} yield target is kept. Automatic adjustment is off.`;
  else{const eligible=recommendations({yield:0,sector:data.get('sector'),term});
   if(eligible.length){const longest=Math.max(...eligible.map(b=>b.years)),suggestion=Math.floor(Math.min(...eligible.filter(b=>b.years===longest).map(b=>b.yield))*10+0.0001)/10,previous=Number(data.get('yield'));
    $('#target-yield').value=suggestion.toFixed(1);
    $('#holding-help').textContent=previous===suggestion?`Suggested yield stays at ${pct(suggestion)} for these choices.`:`Suggested yield: ${pct(previous)} → ${pct(suggestion)}. Move the yield slider to keep your own target.`;
   }else $('#holding-help').textContent='No bonds fit this timeframe, industry and risk preference. Your yield target is unchanged.';
  }
 }
 updateYieldPreview();saveFinderDraft();
}
function preferences(){const f=state.filters;return `<form id="preferences" class="card preferences finder-form"><div class="finder-primary-fields"><div class="field yield-field"><label for="target-yield">Target annual yield</label><div class="yield-readout"><div><span>Minimum yield</span><output id="yield-value" for="target-yield">${f.yield?pct(f.yield):'Any yield'}</output></div><div><span>Annual default rate · Demo</span><output id="default-value">${defaultRange(f)}</output></div></div><input id="target-yield" name="yield" type="range" min="0" max="8" step="0.1" value="${f.yield}" style="--progress:${f.yield/8*100}%" aria-valuetext="${f.yield?pct(f.yield)+' minimum annual yield':'No minimum yield'}" aria-describedby="yield-help"><div class="range-labels"><span>No minimum</span><span>8%</span></div><small id="yield-help">Before tax. A target, not a promise.</small><details class="default-explainer"><summary>What does default rate mean?</summary><p>It describes issuers failing to make promised payments over a year. It is not the percentage of your investment you will lose, and not a prediction about this bond. These demo figures are invented.</p></details></div><div class="field holding-field"><label for="holding-period">Holding period</label><output id="holding-value" for="holding-period">${holdingLabel(f.term)}</output><input id="holding-period" name="term" type="range" min="0" max="31" step="1" value="${f.term}" style="--progress:${f.term/31*100}%" aria-valuetext="${holdingLabel(f.term)}" aria-describedby="holding-help"><div class="range-labels"><span>0</span><span>15 years</span><span>30+ years</span></div><label class="yield-auto"><input id="yield-auto" type="checkbox" ${state.yieldAuto?'checked':''}>Adjust yield automatically</label><small id="holding-help" aria-live="polite">${state.yieldAuto?'Your choices can adjust the suggested yield.':'Your yield target is kept when these choices change.'}</small></div></div><div class="finder-secondary-fields"><label class="field">Industry<select name="sector">${options(['Any sector',...[...new Set(BONDS.map(b=>b.sector))].sort()].map(s=>[s,s]),f.sector)}</select></label><label class="field">Amount to invest ($)<input name="amount" type="number" min="10" max="1000000" step="0.01" value="${f.amount}" required inputmode="decimal"><small class="fractional-help"><strong>Start with $10.</strong> Buy a small part of a bond.</small></label></div><div class="cd-benchmark" id="cd-benchmark" aria-live="polite" aria-atomic="true">${cdBenchmark(f.term,f.yield)}</div><details class="finder-explainer"><summary>About yield, risk and the bank comparison</summary><p id="default-help" aria-live="polite">${defaultHelp(f)}</p><p>0 means less than 1 year; 30+ includes all maturities. Bonds may repay sooner than your chosen period. Selling early can lose money.</p><p>The CD term follows your holding period, where available. APY includes compounding; bond yield assumes you hold to maturity and payments arrive as promised. Risks and early-exit terms differ.</p></details><div class="finder-submit"><span class="small muted">${state.profile.risk==='open'?'Includes higher-risk bonds.':'Investment-grade samples only.'} ${button('Change','profile','aria-label="Change risk preference"','link')}</span>${button('Find my bonds →','filter-submit','type="submit"')}</div><p class="finder-reassurance">We’ll show up to 3 matches. You decide what to explore.</p></form>`}
function startFinderSetup(){if(state.view==='discover'&&!state.profile.complete){pendingOrder=null;profile()}}
function discover(){if(!state.profile.complete)return `<div class="page-heading"><div><div class="eyebrow">Find your first corporate bond</div><h1>A little setup. A clearer starting point.</h1><p>Before we show matches, let’s set up your demo account and explanation style.</p></div></div><section class="card onboarding-start"><h2>Two simple steps to get started</h2><div class="explanation"><p><strong>1. Verify your identity</strong><br>Try a simulated KYC check. No personal documents needed.</p><p><strong>2. Tell us your experience</strong><br>Choose how much explanation you’d like and set a separate risk preference.</p></div>${button('Start account setup →','profile')}<p class="disclosure">Then you can explore bonds by yield, industry and repayment timeframe.</p></section>`;const choosing=state.finderStep==='preferences';const heading=`<div class="page-heading finder-heading"><div><div class="eyebrow">${choosing?'1 · Your preferences':'2 · Your matches'}</div><h1>${choosing?'What are you looking for?':'A few bonds to explore.'}</h1><p>${choosing?'Choose what matters to you. Then we’ll find a few matches.':'Based on your yield, timeframe and industry preferences.'}</p></div>${button('A little more about you','profile','','link')}</div>`;if(choosing)return `<div class="finder-shell">${heading}${preferences()}</div>`;const eligible=recommendations(),matches=topMatches(eligible);return `<div class="finder-results">${heading}<div class="search-summary"><div><span>${state.filters.yield?pct(state.filters.yield)+' minimum yield':'Any yield'}</span><span>${holdingLabel(state.filters.term)}</span><span>${esc(state.filters.sector)}</span><span>${money(Math.round(state.filters.amount*100))}</span></div>${button('Edit preferences','edit-preferences','','secondary')}</div><section aria-label="Bond matches"><div class="results-title" id="results-title" tabindex="-1"><div class="spread"><h2>${matches.length?`Your top ${matches.length} ${matches.length===1?'match':'matches'}`:'No exact matches'}</h2><span class="tag purple">AI guide · Demo</span></div><p>${matches.length?`Selected from ${eligible.length} eligible bonds in our ${BONDS.length}-bond demo pool. ${matches.length<3?'Fewer than three distinct issuers meet your filters; we keep your limits unchanged.':'Three different issuers, ranked for your preferences.'}`:'We won’t increase your risk preference to meet a yield target.'}</p><details class="matching-method"><summary>How we chose these matches</summary><p>Your minimum yield, industry, repayment horizon and credit-risk limit are required. Within those limits, this demo favors stronger credit quality, a yield near your target and earlier repayment. With no minimum yield, higher yield improves the yield score.</p><p>Known issuer and industry overlap in your InCreditble bonds lowers the ranking. Each choice uses a different issuer. Near-identical yield, repayment and credit-quality combinations get less weight so you can compare useful alternatives. Different industries get preference when you leave industry open. External fund exposure is unavailable and is not scored. These are ranked demo matches, not a guarantee of the best investment.</p></details></div>${matches.length?(state.variant==='C'?compare(matches):`<div class="bond-list">${matches.map(bondCard).join('')}</div>`):`<div class="card empty"><h3>Let’s give your search a little more room.</h3><p>Try a lower yield target, another industry or a longer timeframe. Higher yields can come with greater risk.</p>${button('Adjust preferences','edit-preferences','','secondary')}</div>`}<p class="results-footnote">All companies, ratings and yields are fictional. Demo ranking uses explicit rules, not a live AI model. Matches are not a full assessment of suitability.</p></section></div>`}
function reason(b){const f=state.filters;const sector=f.sector==='Any sector'?b.sector+' exposure':b.sector+(b.sector===f.sector?' matches your industry choice':' differs from your industry choice');const yieldNote=f.yield?(b.yield>=f.yield?'meets':'below')+' your '+f.yield+'% yield target':'no minimum yield selected';return `${sector} · ${bondTerm(b)} to repayment · ${yieldNote}.${b.risk>maxRisk()?' Outside your current risk preference.':''}`}
function guideContext(){return {filters:state.filters,experience:state.profile.experience,maxRisk:maxRisk(),bonds:BONDS,totals:totals(),positions:state.positions,cash:state.cash,cds:CD_BENCHMARKS,rankingNotes:Object.fromEntries(topMatches().map(b=>[b.id,b.selectionNote]))}}
function guideRationale(b){const r=BondGuide.rationale(b,guideContext());return `<div class="bond-rationale"><div><strong>Why it matches</strong><p>${esc(r.why)}</p></div><div><strong>The trade-off</strong><p>${esc(r.tradeoff)}</p></div></div>`}
let assistantMessages=[];
function openBondAssistant(id){activeBond=BONDS.find(b=>b.id===id);assistantMessages=[];showDialog('AI bond assistant · Demo',`${activeBond.name} · ${activeBond.sector}`,`<p class="assistant-disclaimer"><span class="tag purple">Demo answers</span> Sample explanations from this bond’s data. No live AI is connected.</p><div class="assistant-context">Selected amount: ${money(Math.round(state.filters.amount*100))} · ${experienceLabel()}</div><div class="assistant-messages" id="assistant-messages" role="log" aria-live="polite" aria-label="Bond explanation conversation"><div class="assistant-message"><strong>Bond assistant</strong><p>I can help you understand this bond, its trade-offs and what the numbers mean. What would you like to know?</p></div></div><div class="assistant-prompts" aria-label="Suggested questions">${['Why this bond?','What are the risks?','How much interest?','Tell me about the company','How would it affect my portfolio?','Compare with a bank CD'].map(q=>button(q,'assistant-question',`data-question="${esc(q)}"`,'secondary')).join('')}</div><form id="assistant-form"><label for="assistant-question">Ask about this bond</label><div class="assistant-input"><input id="assistant-question" name="question" maxlength="400" placeholder="e.g. What if I need to sell early?" required autocomplete="off">${button('Ask','assistant-submit','type="submit"')}</div><p class="small muted">This demo explains; you review and approve any trade.</p></form><div class="modal-actions">${button('Back to bond details','details',`data-id="${activeBond.id}"`,'secondary')}</div>`);$('#dialog').classList.add('assistant-dialog')}
function askBondAssistant(question){const q=question.trim().slice(0,400);if(!q)return;const answers=BondGuide.answer(q,activeBond,guideContext());assistantMessages.push({question:q,answers});$('#assistant-messages').insertAdjacentHTML('beforeend',`<div class="assistant-message user-message"><strong>You</strong><p>${esc(q)}</p></div><div class="assistant-message"><strong>Bond assistant · Sample answer</strong>${answers.map(a=>`<p>${esc(a)}</p>`).join('')}</div>`);$('#assistant-question').value='';const log=$('#assistant-messages');log.scrollTop=log.scrollHeight;$('#assistant-question').focus({preventScroll:true})}
function bondCard(b){return `<article class="card bond-card">${b.matchRank?`<div class="match-rank"><span>${b.matchRank===1?'Top match':'Match '+b.matchRank}</span></div>`:''}<div class="spread"><div class="bond-title"><span class="issuer-icon">${b.icon}</span><div><h3>${b.name}</h3><p>${b.sector} · Fictional issuer</p></div></div></div><div class="match-highlight"><strong>${esc(b.comparisonTitle||'Fits your preferences')}</strong><p>${esc(b.comparisonText||'Compare the yield and repayment time below.')}</p></div><div class="bond-stats"><div><label>${state.profile.experience==='experienced'?'Yield to maturity':'Annual yield'}</label><strong class="yield">${pct(b.yield)}</strong></div><div><label>Repaid in</label><strong>${bondTerm(b)}</strong></div><div><label>Credit quality</label><strong class="text-stat">${b.risk===3?'Higher risk':'Investment grade'}</strong></div></div><details class="match-explanation"><summary>Why this match & about the company</summary><p class="company-glance">${esc(b.company.business)}</p>${guideRationale(b)}<p class="small muted">${esc(b.selectionNote||'')}</p></details>${state.profile.experience==='experienced'?`<p class="technical-line">${b.rating} rating · Par price 100 · Non-callable · Semiannual coupon</p>`:''}<p class="risk-note">${b.risk===3?'Higher default risk. You could lose interest and principal.':'The company could miss payments. Selling early can lose money.'}</p><div class="bond-footer"><span>Fractional orders from $10.<br>Your chosen amount: ${money(Math.round(state.filters.amount*100))}.</span><div class="bond-actions">${button('Ask AI','assistant',`data-id="${b.id}" aria-label="Ask AI about ${esc(b.name)}"`,'secondary')}${button('Understand & buy →','details',`data-id="${b.id}"`)}</div></div></article>`}
function compare(matches){return `<div class="table-scroll"><table class="compare-table"><caption class="small muted" style="text-align:left;padding:10px">Compare fictional corporate bonds</caption><thead><tr><th>Company</th><th>Annual yield</th><th>Repayment</th><th>Credit quality</th><th>Next step</th></tr></thead><tbody>${matches.map(b=>`<tr><td><span class="tag purple">Match ${b.matchRank}</span><strong>${b.name}</strong><small>${b.sector}</small><small>${esc(b.company.business)}</small><small><strong>${esc(b.comparisonTitle)}</strong> · ${esc(b.comparisonText)}</small></td><td>${pct(b.yield)}</td><td>${bondTerm(b)}</td><td>${b.risk===3?'Higher risk':'Investment grade'}</td><td>${button('View bond','details',`data-id="${b.id}"`,'secondary')}</td></tr>`).join('')}</tbody></table></div><p class="risk-note">All bonds can lose value. Issuers can miss payments. Review each bond before buying.</p>`}
function showDialog(title,description,html){$('#dialog').classList.remove('assistant-dialog','schedule-dialog');$('#dialog-content').innerHTML=`<div class="modal-inner"><div class="modal-head"><h2 id="dialog-title">${title}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${description?`<p class="modal-description">${description}</p>`:''}${html}</div>`;if(!$('#dialog').open)$('#dialog').showModal();$('#dialog').scrollTop=0;$('#dialog-content .close').focus()}
function setAccountMenu(open,focusIndex=null){
  const menu=$('#account-menu');
  if(open)menu.innerHTML=`<p class="account-menu-status" role="presentation">${state.signedIn?'Demo account':'Preview mode'}</p><button type="button" role="menuitem" tabindex="-1" data-action="settings">Settings</button><button type="button" role="menuitem" tabindex="-1" data-action="tax-documents">Tax documents</button><button type="button" role="menuitem" tabindex="-1" data-action="${state.signedIn?'logout':'login'}">${state.signedIn?'Log out':'Log in'}</button>`;
  menu.hidden=!open;$('#account-toggle').setAttribute('aria-expanded',String(open));
  if(open&&focusIndex!==null){const items=menu.querySelectorAll('[role="menuitem"]');items[focusIndex<0?items.length-1:focusIndex].focus()}
}
function accountSettings(){showDialog('Settings','Your details and account connections, in one place.',`<div class="settings-list"><button type="button" data-action="profile"><span><strong>About you</strong><small>Identity setup, investing experience and risk preferences.</small></span><span aria-hidden="true">→</span></button><button type="button" data-action="connections"><span><strong>Connected accounts</strong><small>Manage the sample accounts in your portfolio view.</small></span><span aria-hidden="true">→</span></button></div><p class="disclosure">${storageAvailable?'Your demo trades, preferences and sample connections are saved in this browser.':'Browser storage is unavailable. This demo cannot keep changes after refresh.'}</p>${button('Reset demo progress','reset-demo','','link')}`)}
function accountLogin(){showDialog('Log in','Try the account experience with a demo account.',`<div class="explanation"><strong>No password needed for this preview.</strong><p>Use the sample account to explore. Real sign-in is not connected, and no personal information is collected.</p></div><div class="modal-actions">${button('Continue with demo account','demo-login')}</div>`)}
function taxDocuments(){showDialog('Tax documents','Your tax documents will appear here when available.',`<div class="account-empty"><span class="tag">Demo account</span><h3>No tax documents yet</h3><p>Simulated trades do not generate tax documents.</p></div>`)}
document.addEventListener('focusin',e=>{if(!e.target.closest('.account-nav'))setAccountMenu(false)});
document.addEventListener('keydown',e=>{
  if(!e.target.closest('.account-nav'))return;
  const open=!$('#account-menu').hidden;
  if(e.key==='Escape'&&open){e.preventDefault();setAccountMenu(false);$('#account-toggle').focus();return}
  if(e.key==='Tab'){setAccountMenu(false);$('#account-toggle').focus();return}
  if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;
  e.preventDefault();
  if(!open){setAccountMenu(true,e.key==='ArrowUp'||e.key==='End'?-1:0);return}
  const items=[...$('#account-menu').querySelectorAll('[role="menuitem"]')],current=items.indexOf(document.activeElement);
  const next=e.key==='Home'?0:e.key==='End'?items.length-1:(current+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;
  items[next].focus();
});
function closeDialog(){quoteRun++;pendingOrder=null;$('#dialog').close()}
function detail(id){activeBond=BONDS.find(b=>b.id===id);state.detailExpanded=null;renderDetail()}
function companyProfile(b){return `<section class="company-profile" aria-label="Company profile"><div class="spread"><h3>Meet ${esc(b.company.name)}</h3><span class="tag">Fictional profile</span></div><p>${esc(b.company.business)}</p><dl><div><dt>How it earns money</dt><dd>${esc(b.company.income)}</dd></div><div><dt>What to watch</dt><dd>${esc(b.company.watch)}</dd></div></dl><p class="company-boundary">Understanding the business does not guarantee repayment. This is an invented company profile for the demo.</p>${button('Ask AI about this company','assistant-company',`data-id="${b.id}"`,'link')}</section>`}
function renderDetail(){const b=activeBond;const verbose=state.detailExpanded??(state.profile.experience==='new');showDialog(b.name,`${b.sector} · Fictional company and bond`, `<div class="detail-metrics"><div><span>Annual yield</span><strong>${pct(b.yield)}</strong></div><div><span>Repaid in</span><strong>${bondTerm(b)}</strong></div><div><span>Start with</span><strong>$10</strong></div></div>${companyProfile(b)}${guideRationale(b)}<div class="assistant-invite"><div><strong>Want a little more help?</strong><p>Ask about the company, interest or risks.</p></div>${button('Ask AI','assistant',`data-id="${b.id}"`,'secondary')}</div><div class="explanation">${verbose?`<p><strong>You lend money to a company.</strong> In return, it promises interest payments and repayment on ${maturity(b)}.</p><p>In this example, <strong>$100 of face value earns $${b.yield.toFixed(2)} in annualized interest</strong>, assuming the company pays. ${b.years<1?`Over the remaining ${bondTerm(b)}, that is $${(b.yield*b.years).toFixed(2)}.`:"Payments are made twice a year."} This is before tax and excludes real-world fees.</p><p>You can own part of a bond. You don’t need to buy a whole $1,000 unit.</p>`:state.profile.experience==='some'?`<p><strong>$100 of face value earns $${b.yield.toFixed(2)} in annualized interest</strong> if the company pays, before tax and fees. ${b.years<1?`That is $${(b.yield*b.years).toFixed(2)} over the remaining ${bondTerm(b)}.`:"Interest is paid twice a year."}</p><p>Repayment is due on ${maturity(b)}. Selling sooner could return less than you invested. Sample credit rating: ${b.rating}.</p>`:`<p><strong>${pct(b.yield)} yield to maturity</strong> · ${pct(b.yield)} coupon · ${b.rating} sample rating.</p><p>Non-callable. Semiannual payments. Metrics use a $100 reference price; execution quotes differ. No accrued interest in this demo.</p>`}</div>${button(verbose?'Use a shorter explanation':'Explain this in plain language','explain','','link')}<div class="risk-banner"><strong>${b.risk===3?'Higher credit risk':'What could go wrong'}</strong><br>The company could miss interest or fail to repay you. Selling before maturity may return less than you invested.${b.risk===3?' This sample is below investment grade.':''}</div><details><summary>Bond details & pricing assumptions</summary><dl class="definition"><dt>Illustrative annual default rate</dt><dd>${pct(b.defaultRate)}</dd><dt>Sample credit rating</dt><dd>${b.rating}</dd><dt>Coupon rate</dt><dd>${pct(b.yield)}</dd><dt>Repayment date</dt><dd>${maturity(b)}</dd><dt>Interest payments</dt><dd>Apr 9 & Oct 9</dd><dt>Valuation reference per $100 face value</dt><dd>$100.00</dd><dt>Callable</dt><dd>No (demo assumption)</dd><dt>Instrument reference</dt><dd>DEMO-${b.id.toUpperCase()}</dd></dl><p class="disclosure">Displayed yield uses the $100 reference price. Your buy or sell quote is shown next and can change the actual yield. Real quotes, accrued interest, fees and liquidity can change what you receive. No real CUSIP or security is represented.</p></details><div class="modal-actions">${state.positions[b.id]?button('Sell holding','sell',`data-id="${b.id}"`,'secondary'):''}${button('Choose an amount →','buy',`data-id="${b.id}"`)}</div>`)}
function profile(step=null){if(step===null){profileDraft={...state.profile};step=state.profile.complete?2:1;}if(step===1){showDialog('First, let’s set up your account.','Your existing investments can stay where they are. Complete two short steps to explore bonds here; this demo collects no personal documents or bank credentials.',`<p class="steps">Step 1 of 2 · Account setup</p><div class="explanation"><strong>Identity verification (KYC)</strong><p>A real account would need identity checks. This button only completes a simulated identity check.</p></div><p class="disclosure">Your investing experience is a separate question. It changes the explanation style, not whether a bond is safe.</p><div class="modal-actions">${button('Continue with a demo identity →','profile-next')}</div>`)}else showDialog('A little about your experience.','We’ll keep the wording comfortable. You can change it at any time.',`<p class="steps">${state.profile.complete?'Your preferences':'Step 2 of 2 · Your preferences'}</p><form id="profile-form"><fieldset class="choice-group"><legend>How familiar are you with bond investing?</legend>${[['new','I’m new to bonds','Explain the basics with simple dollar examples.'],['some','I’ve invested before','Explain the important trade-offs, with details available.'],['experienced','I know my way around bonds','Show yields, ratings and bond terms up front.']].map(([v,t,d])=>`<label class="choice"><input type="radio" name="experience" value="${v}" ${profileDraft.experience===v?'checked':''}><span><strong>${t}</strong><small>${d}</small></span></label>`).join('')}</fieldset><label class="field">Separately, which credit risk would you like to explore?<select name="risk">${options([['cautious','More cautious — higher-grade companies'],['balanced','Balanced — investment-grade companies'],['open','Include higher-risk companies']],profileDraft.risk)}</select><small>Familiarity does not mean you can afford more risk. This demo preference is not a full suitability assessment.</small></label><div class="modal-actions">${button('Back','profile-back','','secondary')}${button(state.view==='discover'&&!state.profile.complete?'Choose my preferences →':'Save my preferences','profile-save','type="submit"')}</div></form>`)}
function beginOrder(id,side){activeBond=BONDS.find(b=>b.id===id);orderSide=side;if(side==='buy'&&activeBond.risk>maxRisk()){notify('This bond is outside your current risk preference. Review your preferences first.');renderDetail();return}orderCents=side==='buy'?Math.round(state.filters.amount*100):Math.min(state.positions[id]||0,10000);if(!state.profile.complete){pendingOrder={id,side};profile();return}loadQuote()}
function loadQuote(){
 const run=++quoteRun,revision=activeQuote?.bond===activeBond.id?activeQuote.revision+1:0;
 showDialog('Checking demo prices…',activeBond.name,`<div id="quote-loading" class="quote-loading" role="status"><span class="quote-spinner" aria-hidden="true"></span><p>Preparing sample buy and sell quotes.</p><small>No live market is connected.</small></div>`);
 setTimeout(()=>{if(run!==quoteRun||!$('#dialog').open||!$('#quote-loading'))return;activeQuote={...BondQuotes.create(activeBond,revision),bond:activeBond.id};quoteView()},850);
}
function quotePrice(){return activeQuote[orderSide==='buy'?'ask':'bid']}
function quoteView(){
 const q=activeQuote,low=Math.min(...q.history)-10,high=Math.max(...q.history)+10;
 const points=q.history.map((v,i)=>`${i*100},${90-(v-low)/(high-low)*75}`).join(' ');
 showDialog(`${orderSide==='buy'?'Buy':'Sell'} ${activeBond.name}`,'First, take a look at the price.',`<span class="tag purple">Demo quotes · Not live</span><div class="quote-chart"><div class="spread"><span>Recent price movement · Sample session</span><strong>$100.00</strong></div><svg viewBox="0 0 500 100" role="img" aria-label="Illustrative reference price moves from ${money(q.history[0])} to $100 per $100 face value"><path d="M0 95H500" stroke="#ded6e9"/><polyline points="${points}" fill="none" stroke="#633ac3" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg><div class="spread"><small>Earlier ${money(q.history[0])}</small><small>Latest reference $100.00</small></div></div><div class="quote-pair"><div class="${orderSide==='buy'?'selected':''}"><span>You buy at</span><strong>${money(q.ask)}</strong></div><div class="${orderSide==='sell'?'selected':''}"><span>You sell at</span><strong>${money(q.bid)}</strong></div></div><p class="disclosure">Prices are per $100 of face value—the amount due at repayment. Buying and selling have different quotes. This gap is the spread.</p><p class="quote-selected">Your ${orderSide==='buy'?'buy':'sell'} price: <strong>${money(quotePrice())}</strong> per $100 face value.</p><p class="small muted">Invented prices. This demo holds your selected quote until you confirm or request another quote.</p><div class="modal-actions">${button('Refresh demo quotes','refresh-quotes','','secondary')}${button('Continue with this price →','accept-quote')}</div>`);
}
function orderEntry(){const b=activeBond,available=orderSide==='buy'?state.cash:state.positions[b.id]||0;showDialog(`${orderSide==='buy'?'Buy':'Sell'} ${b.name}`,'Choose your amount. Review the final price before confirming.',`<div class="quote-selected">${orderSide==='buy'?'Buy':'Sell'} quote: <strong>${money(quotePrice())}</strong> per $100 face value <span class="tag">Demo</span></div><form id="order-form"><label class="field">${orderSide==='buy'?'Amount to spend ($)':'Face value to sell ($)'}<input class="order-amount" name="amount" id="order-amount" type="number" min="${orderSide==='buy'?'10':'0.01'}" max="${available/100}" step="0.01" value="${(orderCents/100).toFixed(2)}" required inputmode="decimal"><small>${orderSide==='buy'?'Available cash':'Face value held'}: ${money(available)} · InCreditble only</small></label><div class="money-shortcuts">${[1000,10000,50000].filter(c=>c<=available).map(c=>button(dollars(c),'amount',`type="button" data-cents="${c}"`,'secondary')).join('')}${orderSide==='sell'?button('Sell all','amount',`type="button" data-cents="${available}"`,'secondary'):''}</div><div class="order-summary" id="order-estimate"></div><p class="error" id="order-error" role="alert"></p><p class="disclosure">Demo only: no fees or accrued interest. Amounts round to cents. Portfolio values use a $100 reference price; your execution quote differs.</p><div class="modal-actions">${button('Back to prices','quote-view','','secondary')}${button('Review simulated order →','review-order','type="submit" id="review-order"')}</div></form>`);updateEstimate()}
function parseCents(value){if(!/^\d+(\.\d{1,2})?$/.test(value))return null;const n=Math.round(Number(value)*100);return Number.isSafeInteger(n)?n:null}
function updateEstimate(){
 const n=parseCents($('#order-amount').value),available=orderSide==='buy'?state.cash:state.positions[activeBond.id]||0,minimum=orderSide==='buy'?1000:1;
 let err='';if(n===null||n<minimum)err=orderSide==='buy'?'Enter $10 or more, with up to two decimal places.':'Enter a positive face value, with up to two decimal places.';else if(n>available)err=orderSide==='buy'?'Not enough InCreditble cash.':'You can’t sell more than this holding.';
 const a=n===null?null:BondQuotes.amounts(orderSide,n,quotePrice());
 $('#order-error').textContent=err;$('#review-order').disabled=!!err;
 $('#order-estimate').innerHTML=!a?'':`<div><span>Face value ${orderSide==='buy'?'purchased':'sold'}</span><strong>${money(a.face)}</strong></div><div><span>${orderSide==='buy'?'You pay':'You receive'}</span><strong>${money(a.cash)}</strong></div>${orderSide==='buy'?`<div><span>${activeBond.years<1?'Estimated interest to maturity':'Estimated annual interest'}, before tax</span><strong>${money(Math.round(a.face*activeBond.yield/100*Math.min(1,activeBond.years)))}</strong></div>`:''}`;
 return !err;
}
function paymentPreview(face){
 const p=BondQuotes.payments(activeBond,face),date=iso=>new Date(iso+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
 if(!face)return `<div class="payment-preview"><h3>After this sale</h3><p>This position will be closed. No future interest or repayment is expected from it.</p></div>`;
 return `<div class="payment-preview"><h3>${orderSide==='buy'?'What this purchase could pay you':'Your remaining holding after this sale'}</h3><dl><div><dt>Each interest payment</dt><dd>${money(p.coupon)} · Every 6 months</dd></div><div><dt>Next expected interest</dt><dd>${date(p.next)}</dd></div><div><dt>Amount due at repayment</dt><dd>${money(p.principal)} · ${date(p.due)}</dd></div></dl><p>Before tax, assuming the company pays as promised. Selling early can return less than you paid.</p></div>`;
}
function reviewOrder(){
 if(!updateEstimate())return;orderCents=parseCents($('#order-amount').value);
 const a=BondQuotes.amounts(orderSide,orderCents,quotePrice());
 showDialog('Review your final price.','Your quote stays fixed during this demo review.',`<div class="order-summary"><div><span>${orderSide==='buy'?'Buy':'Sell'}</span><strong>${activeBond.name}</strong></div><div><span>Final price per $100 face value</span><strong>${money(quotePrice())}</strong></div><div><span>Face value</span><strong>${money(a.face)}</strong></div><div><span>Fees & accrued interest (demo)</span><strong>$0.00</strong></div><div class="quote-total"><span>${orderSide==='buy'?'Total you pay':'Total you receive'}</span><strong>${money(a.cash)}</strong></div><div><span>Cash afterward</span><strong>${money(state.cash+(orderSide==='buy'?-a.cash:a.cash))}</strong></div></div>${paymentPreview(orderSide==='buy'?a.face:(state.positions[activeBond.id]||0)-a.face)}<p class="disclosure">The $100 portfolio reference and your execution price differ. The spread can reduce your portfolio value. Actual yield can differ from the yield shown at the reference price.</p><label class="check-line"><input type="checkbox" id="confirm-risk"><span>I understand this is a simulation, and real corporate bonds can lose money.</span></label><div class="modal-actions">${button('Edit amount','edit-order','','secondary')}${button(`Confirm simulated ${orderSide}`,'confirm-order','id="confirm-order" disabled')}</div>`);
}
function tradeUpdateMarkup(order){return `<div class="trade-update" role="status"><strong>${order.side==='buy'?'Bought':'Sold'} ${money(order.cents)} · ${esc(order.name)}</strong><p>Cash: ${money(order.cashBefore)} → <strong>${money(order.cashAfter)}</strong><br>This holding: ${money(order.holdingBefore)} → <strong>${money(order.holdingAfter)}</strong>${order.holdingAfter===0?' · Position closed.':''}</p><small>Filled at ${money(order.price)} per $100 face value. Cash ${order.side==='buy'?'paid':'received'}: ${money(order.cents)}. Holdings use the $100 reference price; the spread affects your total value.</small></div>`}
function fillOrder(){
 if(!$('#confirm-risk')?.checked)return;
 const available=orderSide==='buy'?state.cash:state.positions[activeBond.id]||0;
 if(orderCents>available||orderCents<=0){orderEntry();return}
 const b=activeBond,cashBefore=state.cash,holdingBefore=state.positions[b.id]||0,a=BondQuotes.amounts(orderSide,orderCents,quotePrice());
 state.cash+=orderSide==='buy'?-a.cash:a.cash;
 state.positions[b.id]=holdingBefore+(orderSide==='buy'?a.face:-a.face);
 const basis=state.costBasis[b.id]||0;
 if(orderSide==='buy')state.costBasis[b.id]=basis+a.cash;
 else{const released=a.face===holdingBefore?basis:Math.round(basis*a.face/holdingBefore);state.costBasis[b.id]=basis-released;state.realizedPL+=a.cash-released;}
 const order={id:state.orders.length+1,bond:b.id,name:b.name,side:orderSide,cents:a.cash,face:a.face,price:quotePrice(),cashBefore,cashAfter:state.cash,holdingBefore,holdingAfter:state.positions[b.id],time:new Date().toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit',timeZone:'America/Los_Angeles'})};
 state.orders.push(order);state.overviewTab='holdings';render();
 showDialog(orderSide==='buy'?'Your demo bond is in your portfolio.':'Your demo sale is complete.','No real order was sent. Your sample balances have been updated.',`<div class="success-icon" aria-hidden="true">✓</div>${tradeUpdateMarkup(order)}<div class="modal-actions">${button('See updated holdings →','done-order')}</div>`);
}

function connections(){showDialog('Your accounts, together.','Keep your investments where they are. Connect a read-only sample to see its holdings, cash and recent activity alongside your InCreditble account.',`${Object.entries(ACCOUNTS).map(([id,a])=>`<section class="connection"><div class="spread"><div class="account-name"><span class="account-icon">${a.icon}</span><div><strong>${a.name}</strong><div class="small muted">${state.connected[id]?'Sample connected · Read-only':'Demo connection available'}</div></div></div>${button(state.connected[id]?'View access':'Connect sample',state.connected[id]?'access':'connect',`data-id="${id}"`,'secondary')}</div>${state.connected[id]?`<p>${money(accountValue(a))} · ${a.holdings.length} holdings · ${state.sync[id]||'Sample snapshot'}</p><div class="connection-controls">${button('Refresh sample','sync',`data-id="${id}"`,'link')}${button('Disconnect','disconnect',`data-id="${id}"`,'link')}</div>`:''}</section>`).join('')}<p class="disclosure" style="margin-top:22px">No platform is contacted. No login details are requested. These integrations are illustrative and do not imply a partnership.</p>`)}
function access(id){const a=ACCOUNTS[id];showDialog(`Connect ${a.name}`, 'A read-only view. Your assets stay where they are.',`<div class="explanation"><strong>This demo imports:</strong><p>Sample balances, holdings and recent transactions.</p><p>It cannot move money, place orders or change anything at ${a.name}.</p></div><p class="disclosure">In a live product, you would authorize access through a supported provider. This prototype uses a fixed fictional snapshot only.</p><div class="modal-actions">${button('Back','connections','','secondary')}${button(state.connected[id]?'Back to accounts':'Allow sample connection',state.connected[id]?'connections':'allow-connect',`data-id="${id}"`)}</div>`)}
function notify(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500)}
function renderReviewer(){const r=$('#review-controls');r.hidden=!state.review;if(!state.review)return;const names={A:'Focused finder',B:'Guided choices',C:'Comparison table'};r.innerHTML=`<div class="review-bar"><button data-action="variant-prev" aria-label="Previous design">←</button><span>Design ${state.variant} · ${names[state.variant]}</span><button data-action="variant-next" aria-label="Next design">→</button></div><details class="review-panel"><summary>Prototype state · Reviewer only</summary><pre class="review-state">${esc(JSON.stringify(state,null,2))}</pre></details>`}
function variant(delta){const variants=['A','B','C'];state.variant=variants[(variants.indexOf(state.variant)+delta+3)%3];state.view='discover';syncURL();render();startFinderSetup();console.info('Prototype state',JSON.parse(JSON.stringify(state)))}
function about(){showDialog('An idea you can try.','A corporate-bond trading prototype, rebuilt around clarity.',`<p>All companies, prices, ratings, identity checks, external accounts and trades are fictional. No live AI, brokerage, market-data or account-linking service is connected.</p><p class="disclosure" style="margin-top:16px">Demo progress is saved in this browser. Use Settings to reset it. Bond trades use invented buy/sell quotes, a fixed $100 valuation reference, zero accrued interest and zero fees. We have not modeled market execution, transfer restrictions, defaults, tax lots or suitability. External fund balances are separate from direct bond positions.</p><details><summary>Explore other layouts</summary><p><a href="?view=discover&variant=A&review=1">A · Focused finder</a><br><a href="?view=discover&variant=B&review=1">B · Guided choices</a><br><a href="?view=discover&variant=C&review=1">C · Comparison table</a></p></details>`)}

document.addEventListener('click',e=>{if(!e.target.closest('.account-nav'))setAccountMenu(false);const b=e.target.closest('button');if(!b)return;if(b.dataset.nav){navigate(b.dataset.nav);return}if(b.closest('[role=menu]')){setAccountMenu(false);$('#account-toggle').focus()}const id=b.dataset.id;switch(b.dataset.action){case'reset-demo':showDialog('Start this demo again?','This clears saved demo trades, preferences and sample connections in this browser.',`<div class="modal-actions">${button('Keep my progress','settings','','secondary')}${button('Reset demo','confirm-reset-demo')}</div>`);break;case'confirm-reset-demo':resetDemo();break;case'refresh-quotes':loadQuote();break;case'accept-quote':case'edit-order':orderEntry();break;case'quote-view':{const amount=parseCents($('#order-amount').value);if(amount!==null)orderCents=amount;quoteView();break;}case'overview-tab':switchOverviewTab(b.dataset.tab);break;case'edit-preferences':state.finderStep='preferences';render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});break;case'account-menu':setAccountMenu($('#account-menu').hidden,0);break;case'settings':accountSettings();break;case'login':accountLogin();break;case'demo-login':state.signedIn=true;closeDialog();notify('Demo account opened. No real sign-in took place.');break;case'logout':state.signedIn=false;notify('Back to preview mode. Demo holdings are unchanged.');break;case'tax-documents':taxDocuments();break;case'assistant':openBondAssistant(id);break;case'assistant-company':openBondAssistant(id);askBondAssistant('Tell me about the company');break;case'assistant-question':askBondAssistant(b.dataset.question);break;case'portfolio-point':{$('#history-readout').replaceChildren(document.createTextNode(b.dataset.label+' '),Object.assign(document.createElement('strong'),{textContent:b.dataset.value}));document.querySelectorAll('.history-point').forEach(point=>point.setAttribute('aria-pressed',String(point===b)));break;}case'income-month':{const scrollLeft=document.querySelector('.income-chart-scroll').scrollLeft;state.incomeMonth=b.dataset.month;saveDemo();$('#payment-schedule-content').innerHTML=PortfolioIncome.render(earningsSnapshot(),state.incomeMonth,ACCOUNTS);document.querySelector('.income-chart-scroll').scrollLeft=scrollLeft;document.querySelector(`[data-month="${state.incomeMonth}"]`).focus({preventScroll:true});break;}case'overview':navigate('overview');break;case'discover':navigate('discover');break;case'profile':{const form=$('#preferences');if(form&&form.checkValidity()){const d=new FormData(form);state.filters={amount:Number(d.get('amount')),yield:Number(d.get('yield')),sector:d.get('sector'),term:Number(d.get('term'))}}pendingOrder=null;profile();break;}case'profile-next':profileDraft.verified=true;profile(2);break;case'profile-back':profile(1);break;case'close':closeDialog();break;case'details':case'holding':detail(id);break;case'explain':state.detailExpanded=!(state.detailExpanded??(state.profile.experience==='new'));renderDetail();break;case'buy':beginOrder(id,'buy');break;case'sell':beginOrder(id,'sell');break;case'amount':$('#order-amount').value=(Number(b.dataset.cents)/100).toFixed(2);updateEstimate();break;case'confirm-order':fillOrder();break;case'done-order':closeDialog();state.overviewTab='holdings';navigate('overview');$('#overview-panel').focus({preventScroll:true});$('#overview-panel').scrollIntoView({block:'nearest',behavior:'instant'});break;case'connections':connections();break;case'access':case'connect':access(id);break;case'allow-connect':state.connected[id]=true;state.sync[id]='Sample refreshed just now';render();connections();notify(`${ACCOUNTS[id].name} sample added. No real account connected.`);break;case'disconnect':state.connected[id]=false;render();connections();notify(`${ACCOUNTS[id].name} sample removed from this view.`);break;case'sync':state.sync[id]='Sample refreshed just now';render();connections();notify('Sample refreshed. No duplicate holdings or transactions added.');break;case'reset':state.filters={amount:100,yield:0,sector:'Any sector',term:5};render();$('#results-title').focus();break;case'variant-prev':variant(-1);break;case'variant-next':variant(1);break;case'about':about();break}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='assistant-form'){askBondAssistant(new FormData(e.target).get('question'));return}if(e.target.id==='preferences'){const d=new FormData(e.target);state.filters={amount:Number(d.get('amount')),yield:Number(d.get('yield')),sector:d.get('sector'),term:Number(d.get('term'))};state.finderStep='results';render();window.scrollTo({top:0,behavior:'instant'});$('#results-title').focus({preventScroll:true});return}if(e.target.id==='profile-form'){const d=new FormData(e.target);state.profile={verified:true,complete:true,experience:d.get('experience'),risk:d.get('risk')};render();if(pendingOrder){const next=pendingOrder;pendingOrder=null;$('#dialog').close();beginOrder(next.id,next.side)}else{closeDialog();notify('Your explanation style and risk preference are saved for this demo.')}return}if(e.target.id==='order-form')reviewOrder()});
document.addEventListener('input',e=>{if(e.target.id==='order-amount')updateEstimate();if(e.target.id==='target-yield'){state.yieldAuto=false;$('#yield-auto').checked=false;$('#holding-help').textContent='Your target is set. Timeframe and industry changes will keep it.'}if(e.target.closest('#preferences')&&e.target.id!=='yield-auto')updateHoldingPreview(e.target.name==='term'||e.target.name==='sector')});
document.addEventListener('change',e=>{if(e.target.id==='yield-auto'){state.yieldAuto=e.target.checked;updateHoldingPreview(true);saveDemo();return;}if(e.target.id==='history-account'||e.target.id==='history-asset'){const id=e.target.id;state.historyFilters[id==='history-account'?'account':'asset']=e.target.value;render();document.getElementById(id).focus({preventScroll:true});return;}if(e.target.id==='confirm-risk')$('#confirm-order').disabled=!e.target.checked;if(e.target.closest('#preferences'))saveFinderDraft()});
$('#dialog').addEventListener('cancel',()=>{pendingOrder=null;quoteRun++});
document.addEventListener('keydown',e=>{if(document.body.dataset.intro||!state.review||e.target.closest('.account-nav,.overview-tabs')||$('#dialog').open||e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();variant(e.key==='ArrowLeft'?-1:1)}});
window.addEventListener('popstate',()=>{const p=new URLSearchParams(location.search);state.view=p.get('view')==='discover'?'discover':'overview';state.variant=['A','B','C'].includes(p.get('variant'))?p.get('variant'):'A';render();startFinderSetup()});
// Every full load starts at Overview. KYC begins only after entering the finder.
function finishIntro(){
  const intro=$('#welcome-intro');if(intro.hidden)return;
  const moveFocus=intro.contains(document.activeElement)||document.activeElement===document.body;
  intro.hidden=true;$('#app-shell').inert=false;delete document.body.dataset.intro;
  window.scrollTo({top:0,behavior:'instant'});
  if(moveFocus)$('#main').focus({preventScroll:true});
}
$('#skip-intro').addEventListener('click',finishIntro);
syncURL();
render();
